% Tbl = array2table(Data, 'VariableNames', {'price', 'bedrooms', 'bathrooms', 'sqftliving',	'sqftlot' ,'sqftabove', 'sqftbasement' ,'sqftliving15' ,'sqftlot15'});

% corrplot(Tbl);



% Plot the correlation matrix
%corrplot(Tbl);

Y= Data(:,1)/1e6; % Scaling the data in terms of millions of dollars
X1=Data(:,2);
X2=Data(:,3);
X3=Data(:,4);
X4=Data(:,5);
X5=Data(:,6);
X6=Data(:,7);
X7=Data(:,8);
X8=Data(:,9);

val=size(Data);
% Define the feature matrix and target variable
Features = [X1, X2, X3, X4, X5, X6, X7, X8];
X_Normalized = normalize(Features);
Target = Y;  % Express house price in millions of dollars 
Data_Norm_All = [Target X_Normalized]; % Scaled Target and Features
%Data_Norm =  [X1, X2, X3, X4, X5, X6, X7, X8]; % No Target



Tb2 = array2table(Data_Norm_All, 'VariableNames', {'Y', 'X1', 'X2', 'X3', 'X4' ,'X5', 'X6' ,'X7' ,'X8'});
% corrplot(Tb2); % Use when needed

% Constructing the Big X matrix

% Data_Norm =  [normalize(X1), normalize(X2), normalize(X3), normalize(X4), normalize(X5), normalize(X6), normalize(X7), normalize(X8)]; % No Target

% Remove X5 as including it made the X matrix nearly singular

Data_Norm =  [normalize(X1), normalize(X2), normalize(X3), normalize(X4), normalize(X6), normalize(X7), normalize(X8)]; % No Target


X = [ones(val(1),1) Data_Norm];
beta_hat = inv(X'*X)*(X'*Y);

% 0.540182593716745
% -0.054522064949827
% 0.005706574992571
% 0.244176887868176
% 0.001821338224415
% 0.018228353236135
% 0.048925312130714
% -0.023951904493437

% Calculate the predicted values using the estimated coefficients
Predicted_Prices = X * beta_hat;

Compare = [Y Predicted_Prices];

% Do independently with Matlab the R^2 and adjusted R^2

%% R-square calculation

% Total Sum of Squares
SST = sum((Y - mean(Y)).^2);

% Residual Sum of Squares
SSE = sum((Y - Predicted_Prices).^2);

% Regression Sum of Squares
SSR = sum((Predicted_Prices - mean(Y)).^2);

% R-square
R2 = 1 - (SSE / SST);

disp('R-square:')
disp(R2)

%% Adjusted R-square

n = length(Y);      % Number of observations
p = size(X,2) - 1;  % Number of predictors

Adj_R2 = 1 - ((SSE/(n-p-1)) / (SST/(n-1)));

disp('Adjusted R-square:')
disp(Adj_R2)


